function e(e=1,t=`EUR`){return{name:`Sous-jacent ${e}`,ticker:``,ccy:t,sigma:20,q:2,sigma_fx:0,rho_sfx:0,ccyh:0,dividendCurveEnabled:!1,dividendDecay:10,v0:4,kappa:2,theta:4,xi:35,rho_h:-70,rho_rS:40,alpha:20,beta:50,rho:-30,nu:40,skew:-10,curvature:5,showQuanto:!1,asset_class:`unknown`,vol_surface:null,_smileDefaults:!0,vol_level_source:`default`}}var t=[`sigma`,`q`,`sigma_fx`,`rho_sfx`,`v0`,`theta`,`xi`,`rho_h`,`rho_rS`,`alpha`,`beta`,`rho`,`nu`,`skew`,`curvature`];function n(e){return Math.round(Number(e)*1e6)/1e4}function r(e){let[t,n=`0`]=String(Number(e)).split(`e`);return Number(`${t}e${Number(n)+2}`)}export{r as i,e as n,n as r,t};